ee:message.ee:set-payload:
%dw 2.0
output application/json
var error = vars.vErrorMsg default {}
---
{
  message: {
    subject: "Missing Documents For The Automation",
    importance: "high",
    body: {
      contentType: "HTML",
      content:
        "<p>Hi Team,</p>" ++
        "<p>This is to inform you that the <b> Inventory and Rack Reports </b> processing has failed during the automation.</p>" ++
        "<table border='1' cellpadding='5' cellspacing='0' style='border-collapse: collapse;'>" ++
          "<tr><th>Field</th><th>Value</th></tr>" ++
          "<tr><td>Info</td><td>" ++ "Automation Failed Due to Missing Documents" ++ "</td></tr>" ++
          "<tr><td>Document Name</td><td>" ++ (vars.missingDocMessage) ++ "</td></tr>" ++
          "<tr><td>Email Received Date Time</td><td>" ++ (vars.vReceivedDatetime) ++ "</td></tr>" ++
          "<tr><td>Error Type</td><td>" ++ "CUSTOM:MISSING_DOCUMENTS" ++ "</td></tr>" ++
          "<tr><td>Error Message</td><td>" ++ "There were missing Attachments in Email received" ++ "</td></tr>" ++
          "<tr><td>Failing Component</td><td>" ++ "Attachments Validation" ++ "</td></tr>" ++
          "<tr><td>Timestamp (UTC)</td><td>" ++ ((error.Timestamp)) ++ "</td></tr>" ++
        "</table>" ++
        "<p>Thank you</p>"
    },
    toRecipients: (p('mail.to') splitBy ",") map (email) -> {
      emailAddress: {
        address: trim(email)
      }
    },
    ccRecipients: (p('mail.cc') splitBy ",") map (email) -> {
      emailAddress: {
        address: trim(email)
      }
    }
  },
  saveToSentItems: false
}

%dw 2.0
output application/json
---
{
  message: {
    subject: "Inventory and Rack Reports Processing Failed",
    body: {
      contentType: "HTML",
      content: 
        "<p>Hi Team,</p>" ++

        "<p>This is to inform you that the <b>Inventory and Rack Reports</b> processing has failed during the automation.</p>" ++

        "<p><b>Cause:</b> The Crude Received from pipeline value is not available for the Inventory Date: <b>" ++ (vars.inventoryDate as String) ++ "</b>.</p>" ++

        "<p>Kindly update the required Crude Received from pipeline value for the mentioned Inventory Date and reprocess the job.</p>" ++

        "<p>Thank you</p>"
    },
    toRecipients: (p('mail.to') splitBy ",") map (email) -> {
      emailAddress: {
        address: trim(email)
      }
    },
    ccRecipients: (p('mail.cc') splitBy ",") map (email) -> {
      emailAddress: {
        address: trim(email)
      }
    }
  },
  saveToSentItems: false
}

%dw 2.0
output application/json
var error = vars.vErrorMsg default {}
---
{
  message: {
    subject: "Inventory and Rack Reports Processing Failed",
    body: {
      contentType: "HTML",
      content: 
        "<p>Hi Team,</p>" ++
        "<p>This is to inform you that the <b>Inventory and Rack Reports</b> processing has failed during the automation.<b>" ++ "</b></p>" ++
        "<table border='1' cellpadding='5' cellspacing='0' style='border-collapse: collapse;'>"
          ++ "<tr><th>Field</th><th>Value</th></tr>" ++
          "<tr><td>Info</td><td>" ++ (error.Info default "-") ++ "</td></tr>" ++
          "<tr><td>Document Name</td><td>" ++ ((vars.allPDFs default []) map ($ as String) joinBy "<br>") ++ "</td></tr>" ++
          "<tr><td>Inventory Date</td><td>" ++ (error.'Date' default "-") ++ "</td></tr>" ++
          "<tr><td>Email Received DateTime</td><td>" ++ (vars.vReceivedDatetime default "-") ++ "</td></tr>" ++
          "<tr><td>Error Type</td><td>" ++ (error.ErrorType default "-") ++ "</td></tr>" ++
          "<tr><td>Error Message</td><td>" ++ (error.ErrorMessage default "-") ++ "</td></tr>" ++
          "<tr><td>Failing Component</td><td>" ++ (error.'FailingComponent' default "-") ++ "</td></tr>" ++
          "<tr><td>Timestamp (UTC)</td><td>" ++ (error.Timestamp default "-") ++ "</td></tr>" ++
        "</table>" ++
        "<p>Thank you</p>"
    },
    toRecipients: p('mail.to') splitBy "," map (email) -> {
      emailAddress: {
        address: trim(email)
      }
    },
    ccRecipients: p('mail.cc') splitBy "," map (email) -> {
      emailAddress: {
        address: trim(email)
      }
    }},
  saveToSentItems: "false"
}
